const recentDataSourceRowEvents = `-- name: RecentDataSourceRowEvents :many
SELECT id, tenant_id, source_id, entity_key, payload, operation, ts, source_ip, auth_token_id
FROM data_source_row_events
WHERE source_id = $1 AND tenant_id = $2 AND ts >= $3
ORDER BY ts DESC
LIMIT $4
`

type RecentDataSourceRowEventsParams struct {
	SourceID int64              `json:"source_id"`
	TenantID int64              `json:"tenant_id"`
	Ts       pgtype.Timestamptz `json:"ts"`
	Limit    int32              `json:"limit"`
}

// Small window of the most recent events for the History widget's
// "recent changes" list. Payload is included so the UI can render the
// row's current shape without a second lookup. Kept separate from the
// bucket query so the caller can tune the two limits independently.
func (q *Queries) RecentDataSourceRowEvents(ctx context.Context, arg RecentDataSourceRowEventsParams) ([]DataSourceRowEvent, error) {
	rows, err := q.db.Query(ctx, recentDataSourceRowEvents,
		arg.SourceID,
		arg.TenantID,
		arg.Ts,
		arg.Limit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []DataSourceRowEvent{}
	for rows.Next() {
		var i DataSourceRowEvent
		if err := rows.Scan(
			&i.ID,
			&i.TenantID,
			&i.SourceID,
			&i.EntityKey,
			&i.Payload,
			&i.Operation,
			&i.Ts,
			&i.SourceIp,
			&i.AuthTokenID,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const sampleDataSourceRowFields = `-- name: SampleDataSourceRowFields :many

SELECT DISTINCT jsonb_object_keys(payload) AS field_key
FROM (
  SELECT payload FROM data_source_rows
  WHERE source_id = $1 AND tenant_id = $2
  ORDER BY updated_at DESC
  LIMIT $3
) sub
ORDER BY field_key
`

type SampleDataSourceRowFieldsParams struct {
	SourceID int64 `json:"source_id"`
	TenantID int64 `json:"tenant_id"`
	Limit    int32 `json:"limit"`
}

// ============================================================ source hints
// Returns the union of top-level payload keys across the most recently
// updated N rows for a source. Used by the builder's field picker when
// the source is REST / file / webhook (i.e. no fixed schema — table
// sources use table_field_definitions instead). Rows are fetched via a
// subquery so DISTINCT operates on the sampled set, not the whole
// table. `sample` should be small (100–500 rows is plenty).
func (q *Queries) SampleDataSourceRowFields(ctx context.Context, arg SampleDataSourceRowFieldsParams) ([]string, error) {
	rows, err := q.db.Query(ctx, sampleDataSourceRowFields, arg.SourceID, arg.TenantID, arg.Limit)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []string{}
	for rows.Next() {
		var field_key string
		if err := rows.Scan(&field_key); err != nil {
			return nil, err
		}
		items = append(items, field_key)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

