const updateReport = `-- name: UpdateReport :one
UPDATE reports
SET name = $3, description = $4, icon = $5, color = $6,
    spec = $7, spec_version = $8, zone_id = $9, updated_at = now()
WHERE id = $1 AND tenant_id = $2
RETURNING id, tenant_id, name, description, icon, color, spec, spec_version,
          is_archived, created_by, created_at, updated_at, zone_id
`

type UpdateReportParams struct {
	ID          int64           `json:"id"`
	TenantID    int64           `json:"tenant_id"`
	Name        string          `json:"name"`
	Description string          `json:"description"`
	Icon        string          `json:"icon"`
	Color       string          `json:"color"`
	Spec        json.RawMessage `json:"spec"`
	SpecVersion int32           `json:"spec_version"`
	ZoneID      pgtype.Int8     `json:"zone_id"`
}

// Full update. Handler always sends every field — patch semantics live
// above this. `updated_at` is bumped explicitly so the directory sort
// ("recently updated") tracks meaningful changes, not silent DB writes.
func (q *Queries) UpdateReport(ctx context.Context, arg UpdateReportParams) (Report, error) {
	row := q.db.QueryRow(ctx, updateReport,
		arg.ID,
		arg.TenantID,
		arg.Name,
		arg.Description,
		arg.Icon,
		arg.Color,
		arg.Spec,
		arg.SpecVersion,
		arg.ZoneID,
	)
	var i Report
	err := row.Scan(
		&i.ID,
		&i.TenantID,
		&i.Name,
		&i.Description,
		&i.Icon,
		&i.Color,
		&i.Spec,
		&i.SpecVersion,
		&i.IsArchived,
		&i.CreatedBy,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.ZoneID,
	)
	return i, err
}

const upsertReportPermission = `-- name: UpsertReportPermission :exec
INSERT INTO report_permissions (report_id, user_id, can_edit, granted_by)
VALUES ($1, $2, $3, $4)
ON CONFLICT (report_id, user_id) DO UPDATE
SET can_edit = EXCLUDED.can_edit, granted_at = now(), granted_by = EXCLUDED.granted_by
`

type UpsertReportPermissionParams struct {
	ReportID  int64       `json:"report_id"`
	UserID    int64       `json:"user_id"`
	CanEdit   bool        `json:"can_edit"`
	GrantedBy pgtype.Int8 `json:"granted_by"`
}

func (q *Queries) UpsertReportPermission(ctx context.Context, arg UpsertReportPermissionParams) error {
	_, err := q.db.Exec(ctx, upsertReportPermission,
		arg.ReportID,
		arg.UserID,
		arg.CanEdit,
		arg.GrantedBy,
	)
	return err
}
